item.content:encoded:
/*
Welcome to Custom CSS!

To learn how this works, see http://wp.me/PEmnE-Bt
*/
/* Images */
img {
	max-width: 100%;
	height: auto;
	padding-top: 0;
	padding-right: 0;
	padding-bottom: 0;
	padding-left: 0;
}

/*slideshow*/
.slideshow-window {
	background-color: #d6d6d6;
	border-color: #ef7c27;
	border-width: 1px;
}

/* attachment pages wordpress */
.attachment .entry-content .entry-caption {
	font-size: 140%;
	margin-top: 24px;
}

.attachment .entry-content .nav-previous a:before {
	content: '\2190\\\\\\\\\\\\\\\\\\\\\\\\\\00a0';
}

.attachment .entry-content .nav-next a:after {
	content: '\00a0\\\\\\\\\\\\\\\\\\\\\\\\\\2192';
}

.entry-attachment p.attachment a {
	display: block;
	padding: 1px;
}

.entry-attachment p.attachment img {
	display: block;
}

.entry-attachment p.attachment {
}

.entry-attachment .navigation {
	clear: both;
}

.wp-caption {
	margin-top: .4em;
}

.wp-caption {
	margin: 0 0 20px;
	padding: 0;
	max-width: 100%;
	display: block;
}

.wp-caption img {
	margin: 0;
}

.wp-caption .wp-caption-text,
.gallery-caption {
	font-size: 11px;
	font-style: italic;
}

.wp-caption .wp-caption-text {
	margin-bottom: 0;
	padding-top: 0;
	padding-right: 0;
	padding-bottom: 0;
	padding-left: 0;
	position: relative;
}

.posttitle {
	margin: 0 0 13px;
	overflow: hidden;
	word-wrap: break-word;
}

.posttitle, .posttitle a {
	font-size: 16px;
}

.posttitle a:hover {
	text-decoration: none;
}

#postattachment .entry-utility {
	width: 100%;
	float: none;
	padding: 20px;
}

.entry-attachment {
	margin-bottom: 20px;
}

/* heading */
h1, h2 {
	margin-bottom: 20px;
}

h3, h4, h5 {
	margin-bottom: 10px;
}

h1 {
	font-size: 20px;
}

h2 {
	font-size: 18px;
}

h3 {
	font-size: 16px;
}

h4 {
	font-size: 14px;
}

h5 {
	font-size: 12px;
}

h6 {
	font-size: 10px;
}

h1, h2, h3, h4, h5, h6 {
	font-weight: bold;
	line-height: normal;
	font-family: 'Droid Sans', sans-serif;
}

.alignleft.titleicon {
	margin: 4px 5px 0 10px;
}

.pagetitle {
	font-size: 28px;
	font-weight: bold;
	margin-bottom: 0;
	float: left;
}

.pagedesc {
	margin: 0 0 0 10px;
	padding: 6px 0 0;
	float: left;
}

.margin_bottomoff {
	margin-bottom: 0;
}

.frame {
	padding: 1px;
}

/* 1. GLOBAL ELEMENTS
--------------------------------------------------------------------------------------*/
body {
	color: black;
	background-color: #e7e7e7;
	background-repeat: repeat;
/* You can choose the background image from here. just take one of background-image from below. */
	background-image: url(images/pattern.png);
}

/*======== Elements ========*/
/* Main global 'theme' and typographic styles */
body {
	font-family: Arial, Helvetica, sans-serif;
	color: #656565;
	font-size: 16px;
	line-height: 30px;
}

/* 6. FOOTER SIDEBAR SECTION 
--------------------------------------------------------------------------------------*/
#outerfootersidebar {
	background: #eeeeee url(images/pattern2.png);
	border-top: 2px solid #ef7c27;
	border-bottom: 2px solid #ef7c27;
	color: #999;
}

#footersidebar {
}

#footersidebar .widget-title {
	color: #4f4f4f;
}

#footersidebar li {
	border-bottom: 1px solid #474747;
}

#footersidebar li a, #footersidebar li a:visited {
	color: #999;
}

#footersidebar li a:hover, #footersidebar li a.colortext {
	color: #e77724;
}

#footersidebar .frame {
	border: 1px solid #474747;
}

#footersidebar ul.sub-menu li, #footersidebar ul.children li, #footersidebar ul ul ul li {
	border-top: 1px solid #474747;
	border-bottom: 0;
}

#footersidebar blockquote:before, #footersidebar blockquote {
	color: #e4e4e4;
}

/* Tag */
.tags a {
	border: solid 1px #f0f0f0;
	color: #888;
}

.tags a:hover {
	background: #f8f8f8;
	color: #888;
}

.gallery-pic img {
	border: 1px solid #474747;
	color: #363636;
}

#shadowbottom {
	background: url(images/shadow-content-bottom.png) repeat-x;
}

/* 7. FOOTER SECTION 
--------------------------------------------------------------------------------------*/
#outerfooter {
	border-top: solid 0 #363636;
	background: #d6d6d6;
}

#footer {
	color: #999;
}

#footer a, #footer a:visited {
	color: #e77724;
}

#footer a:hover {
	color: #eee;
}

